const lines = require('fs').readFileSync('/dev/stdin', 'utf8').split('\n');
const n = parseInt(lines[0]);
const s = lines[1];

let count = 0;
let run = 0;

for (let i = 0; i < n; i++) {
    if (s[i] === 'x') {
        run++;
    } else {
        if (run >= 3) count += run - 2;
        run = 0;
    }
}
if (run >= 3) count += run - 2;

